    {
      "id": "H1",
      "claim": "The model exploits trial-specific signatures (e.g., task direction) that transfer to new trials within the same subject/session.",
      "mechanism": "Task-level information shared across windows of a single trial allows generalization from training windows to test windows on unseen trials, driving high window split performance but low trial split performance.",
      "supporting_evidence_ids": ["obs_1", "req_1"],
      "limitations": "Does not account for subject-specific identity effects or domain shifts."
    },
    {
      "id": "H2",
      "claim": "The model exploits subject/session identities (identity/collection effects) rather than trial content.",
      "mechanism": "Labels are correlated with unseen metadata features of the test subjects/sessions, causing high performance when those entities overlap between train and test sets but failing on truly disjoint ones.",
      "supporting_evidence_ids": ["obs_1", "req_1"],
      "limitations": "Cannot distinguish from trial-specific effects without permutation tests."
    }
  ],
  "request_id": "req_2",
  "tool_id": "trial_shuffle_within_subject",
  "parameters": {},
  "distinguishes": ["H1", "H2"],
  "prediction": {
    "scoring_status": "numeric",
    "metric_key": "trial_shuffle_trial_ba_mean",
    "primary_direction": "near_zero",
    "threshold": 0.05,
    "check_facts": null,
    "conditional_predictions": [
      {"hypothesis_id": "H1", "direction": "positive", "rationale": "If trial content drives performance, shuffling labels within a subject should break the task mapping for each new label assignment, reducing BA to chance."},
      {"hypothesis_id": "H2", "direction": "negative", "rationale": "If identity effects drive performance, permuting labels within subjects while preserving counts might still allow some leakage if metadata correlates with class; however, the primary expectation for H1 is a drop in BA."}
    ],
    "update_rule_if_opposite": "If trial_shuffle_trial_ba_mean remains high (>0.5), this suggests identity effects (H2) or that shuffling does not break the underlying signal sufficiently to distinguish from content-based transfer."
  },
  "reasoning_summary": "Shuffle labels within subjects to test if performance relies on subject-specific identities (H2) vs trial-level task mapping (H1). Expect BA drop near chance for H1, stable high BA for H2."
}

